function live_panel_exists(string $key): bool
{
    return in_array($key, ['build', 'team', 'seo', 'write', 'social', 'crm', 'calendar', 'bot', 'creative', 'video', 'automation', 'aria', 'domains', 'email', 'hosting', 'cc', 'workspaces'], true);
}

/** Which panel illustrates a product page. */
function live_panel_for_product(string $slug): string
{
    $map = ['website-builder' => 'build', 'ai-workforce' => 'team', 'seo' => 'seo', 'content' => 'write', 'social' => 'social', 'crm' => 'crm',
        'calendar' => 'calendar', 'chatbot' => 'bot', 'creative' => 'creative', 'video' => 'video', 'automation' => 'automation', 'aria' => 'aria',
        'domains' => 'domains', 'business-email' => 'email', 'hosting' => 'hosting'];
    return $map[$slug] ?? '';
}

