            $h = '<div class="lg-glass lg-glass--thick lg-stack lv-chat lv-chat--wide"><div class="lg-row gap-2 lv-chat__head"><img class="lg-avatar lg-presence" src="' . $av('aria') . '" alt="" width="36" height="36"><div class="lg-stack"><span class="t-subhead t-strong">Aria</span><span class="t-caption c-3">Knows the platform</span></div></div><div class="lg-stack gap-2 lv-chat__body"><div class="lg-bubble lg-bubble--me lv-b" data-lv="m">How do I connect the domain I already own?</div><div class="lg-typing lg-glass lg-glass--thin" data-lv="typing" hidden><i></i><i></i><i></i></div><div class="lg-bubble lv-b" data-lv="m">Three steps, about ten minutes:<br>1. Websites → your site → <b>Connect a domain</b>.<br>2. Add the two records we show you at your registrar.<br>3. We check every minute and switch SSL on when they resolve.<br>Want me to open that screen for you?</div><div class="lg-bubble lg-bubble--me lv-b" data-lv="m">Yes please.</div><div class="lg-bubble lv-b" data-lv="m">Done, it\'s open on your left. I\'ll tell you when the records resolve.</div></div><div class="lv-chat__composer"><div class="lg-composer__field lg-glass lg-glass--thick"><span class="lg-composer__input"><span data-lv="typed"></span><span class="lv-caret" data-lv="caret" hidden></span></span></div></div></div>';
            break;
        case 'domains':
            $h = '<div class="lg-stack gap-3"><div class="lg-glass lg-glass--thick lv-search"><span class="lv-search__q"><span data-lv="typed">blackdoor.com</span><span class="lv-caret" data-lv="caret" hidden></span></span><span class="lg-btn lg-btn--primary lg-btn--sm">Search</span></div><div class="lg-glass lg-card lv-card lg-stack gap-1"><div class="lv-dom" data-lv="dom"><span class="t-subhead t-strong">blackdoor.com</span><span class="lg-badge lg-badge--success">Available</span></div><div class="lv-dom" data-lv="dom"><span class="t-subhead t-strong">blackdoor.co.uk</span><span class="lg-badge lg-badge--success">Available</span></div><div class="lv-dom" data-lv="dom"><span class="t-subhead t-strong">blackdoor.restaurant</span><span class="lg-badge lg-badge--success">Available</span></div><div class="lv-dom" data-lv="dom"><span class="t-subhead t-strong">blackdoor.uk</span><span class="lg-badge">Taken</span></div></div>'
               . '<div class="lg-glass lg-card lv-card lg-stack gap-2"><span class="t-eyebrow">blackdoor.com</span><div class="lv-checks lv-checks--row"><span class="lv-check" data-lv="step">' . $check . 'Registered to you</span><span class="lv-check" data-lv="step">' . $check . 'Connected to your site</span><span class="lv-check" data-lv="step">' . $check . 'SSL on</span><span class="lv-check" data-lv="step">' . $check . 'Auto-renew on</span></div></div></div>';
            break;
        case 'email':
            $h = '<div class="lg-glass lg-glass--thick lg-stack lv-mail"><div class="lg-row lg-between lv-mail__head"><span class="t-subhead t-strong">hello@blackdoor.com</span><span class="lg-badge lg-badge--success">' . $check . 'Your domain</span></div>'
               . '<div class="lv-mailrow" data-lv="mail"><span class="lg-avatar lv-av-letter">E</span><div class="lg-stack lg-grow"><span class="t-subhead t-strong">Emma Clarke · Private hire on 14 Oct?</span><span class="t-caption c-2">Hi, we\'d love the long table for twelve…</span></div><span class="t-caption c-3">11:04 pm</span></div>'
               . '<div class="lv-mailrow" data-lv="mail"><span class="lg-avatar lv-av-letter" style="background:var(--tint);color:var(--accent-text)">S</span><div class="lg-stack lg-grow"><span class="t-subhead t-strong">Sarah · Re: Private hire on 14 Oct?</span><span class="t-caption c-2">Menu and prices attached, the room is yours if…</span></div><span class="t-caption c-3">11:06 pm</span></div>'
               . '<div class="lv-mailrow" data-lv="mail"><span class="lg-avatar lv-av-letter">T</span><div class="lg-stack lg-grow"><span class="t-subhead t-strong">Tom Harker · Table for 6 on Saturday</span><span class="t-caption c-2">Is 7:30 possible? We have a birthday…</span></div><span class="t-caption c-3">9:12 pm</span></div>'
               . '<div class="lv-mailrow" data-lv="mail"><span class="lg-avatar lv-av-letter">R</span><div class="lg-stack lg-grow"><span class="t-subhead t-strong">Riverside Farm · Invoice 2214</span><span class="t-caption c-2">This week\'s veg box, paid by card…</span></div><span class="t-caption c-3">4:40 pm</span></div>'
               . '<div class="lg-row lg-between lv-mail__foot"><span class="t-caption c-3">On your phone and your laptop, spam filtered</span><span class="t-caption c-3" data-lv="count">4 new</span></div></div>';
            break;
        case 'hosting':
            $h = '<div class="lv-cols lv-cols--host"><div class="lg-glass lg-card lv-card lg-stack gap-1"><span class="t-eyebrow">Uptime · 30 days</span><b class="lv-big t-num" data-lv="up">99.99%</b><div class="lg-meter"><i data-lv="meter" data-to="100"></i></div></div><div class="lg-glass lg-card lv-card lg-stack gap-1"><span class="t-eyebrow">Response</span><b class="lv-big t-num"><span data-lv="ms">118</span> ms</b><div class="lg-meter"><i data-lv="meter" data-to="88"></i></div></div><div class="lg-glass lg-card lv-card lg-stack gap-1"><span class="t-eyebrow">SSL</span><b class="lv-big">On</b><span class="t-caption c-2" data-lv="ssl">Renewed 3 days ago · next in 87 days</span></div><div class="lg-glass lg-card lv-card lg-stack gap-1"><span class="t-eyebrow">Backups</span><b class="lv-big">Daily</b><span class="t-caption c-2" data-lv="bk">Last one 2 h ago · restore in one click</span></div><div class="lg-glass lg-card lv-card lg-stack gap-2 lv-span"><span class="t-eyebrow">Traffic today</span><div class="lv-bars">' . implode('', array_map(fn ($v) => '<i data-lv="bar" style="height:' . $v . '%"></i>', [22, 30, 26, 41, 58, 47, 66, 74, 61, 83, 90, 72, 54, 60])) . '</div><span class="t-caption c-2">Cached at the edge, served from the nearest city</span></div></div>';
            break;
        case 'cc':
            $h = '<div class="lv-app"><aside class="lv-side"><div class="lg-row gap-2 lv-side__brand"><img src="/img/logo-icon-40.png" alt="" width="20" height="20"><span class="t-subhead t-strong">LevelUpGrowth</span></div><div class="lv-nav"><img class="lg-avatar" src="' . $av('sarah') . '" alt="" width="20" height="20">Sarah</div><span class="t-eyebrow lv-side__h">Workspace</span><div class="lv-nav is-on">Command Center</div><div class="lv-nav">Strategy Room</div><div class="lv-nav">Campaigns</div><div class="lv-nav">Review Queue<span class="lg-count" data-lv="pending">2</span></div><span class="t-eyebrow lv-side__h">Engines</span><div class="lv-nav">Clients</div><div class="lv-nav">SEO</div><div class="lv-nav">Write</div><div class="lv-nav">Social</div></aside>'
               . '<div class="lv-main"><div class="lg-row lg-between"><div class="lg-stack"><span class="t-title3">Good morning, Owner.</span><span class="t-caption c-3">7 agents on this workspace</span></div><span class="lg-badge lg-badge--success"><span class="lg-dot"></span>LIVE</span></div><div class="lv-stats"><div class="lg-glass lg-card lg-stat lv-stat-card"><span class="t-eyebrow">Tasks done</span><span class="lg-stat__value" data-lv="count" data-n="51">51</span></div><div class="lg-glass lg-card lg-stat lv-stat-card"><span class="t-eyebrow">Published</span><span class="lg-stat__value" data-lv="count" data-n="12">12</span></div><div class="lg-glass lg-card lg-stat lv-stat-card"><span class="t-eyebrow">Leads</span><span class="lg-stat__value" data-lv="count" data-n="34">34</span></div><div class="lg-glass lg-card lg-stat lv-stat-card"><span class="t-eyebrow">Keywords</span><span class="lg-stat__value" data-lv="count" data-n="8">8</span></div></div>'
               . '<div class="lg-glass lg-card lg-stack lv-card" style="gap:0"><div class="lg-row lg-between lv-card__head"><span class="t-eyebrow">Your team right now</span></div><div class="lg-row-item lv-evt"><img class="lg-avatar lg-avatar--sm" src="' . $av('elena') . '" alt=""><div class="lg-stack"><span class="t-subhead">Elena captured a new lead</span><span class="t-caption c-3">just now</span></div></div><div class="lg-row-item lv-evt"><img class="lg-avatar lg-avatar--sm" src="' . $av('marcus') . '" alt=""><div class="lg-stack"><span class="t-subhead">Marcus scheduled Friday\'s post</span><span class="t-caption c-3">2 minutes ago</span></div></div><div class="lg-row-item lv-evt"><img class="lg-avatar lg-avatar--sm" src="' . $av('priya') . '" alt=""><div class="lg-stack"><span class="t-subhead">Priya finished: Autumn menu article</span><span class="t-caption c-3">18 minutes ago</span></div></div></div></div></div>';
            break;
        case 'workspaces':
            $ws = fn (string $name, string $site, string $credits, string $ev1, string $ev2, string $a1, string $a2) => '<div class="lg-glass lg-card lv-card lg-stack gap-2" data-lv="ws"><div class="lg-row lg-between"><span class="t-subhead t-strong">' . $name . '</span><span class="lg-badge lg-badge--success"><span class="lg-dot"></span>Live</span></div><span class="t-caption c-2">' . $site . '</span><div class="lg-meter"><i data-lv="meter" data-to="' . $credits . '"></i></div><span class="t-caption c-3">' . $credits . '% of this month\'s credits used</span><div class="lg-row-item lv-evt"><img class="lg-avatar lg-avatar--sm" src="' . $av($a1) . '" alt=""><span class="t-subhead">' . $ev1 . '</span></div><div class="lg-row-item lv-evt"><img class="lg-avatar lg-avatar--sm" src="' . $av($a2) . '" alt=""><span class="t-subhead">' . $ev2 . '</span></div></div>';
            $h = '<div class="lg-stack gap-3"><div class="lg-row lg-between"><span class="t-eyebrow">Your clients</span><span class="lg-badge lg-badge--brand">White-label · your name on it</span></div><div class="lv-cols">' . $ws('Black Door · restaurant', 'blackdoor.com · 3 sites', '62', 'Priya published the autumn menu', 'Elena logged 4 enquiries', 'priya', 'elena') . $ws('Forge Athletic · gym', 'forgeathletic.co.uk · 1 site', '38', 'Marcus scheduled the week', 'James fixed 6 quick wins', 'marcus', 'james') . '</div><div class="lg-toast lg-glass lg-glass--thick lv-toast" data-lv="toast"><span class="lg-toast__icon">' . $check . '</span><span class="t-subhead t-strong">Two workspaces, one login, one invoice to each client</span></div></div>';
            break;
    }
    return '<figure class="lv lg-glass lg-glass--thick" data-live="' . e($key) . '"><div class="lv-bar"><i></i><i></i><i></i><span class="lv-url">' . e($url) . '</span></div><div class="lv-body">' . $h . '</div>'
         . ($caption !== '' ? '<figcaption class="lv-cap">' . e($caption) . '</figcaption>' : '') . '</figure>';
}
